  ADD COLUMN IF NOT EXISTS avg_color VARCHAR(9) NULL DEFAULT NULL AFTER thumb_path,
  ADD COLUMN IF NOT EXISTS lqip TEXT NULL DEFAULT NULL AFTER avg_color;

